// single-item input: the form emits one submission and everything below is
// about that one release.
//
// Read the form by name, not from $input. Settings sits between the two, and a
// Set node in manual mode REPLACES the item - so $input here would be the config
// and every form field would be undefined.
const f = $('Check Coverage').first().json;

function host(s) {
  return String(s || '')
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/[\/?#].*$/, '');
}

const url = String(f['Press release URL'] || '').trim();
if (!/^https?:\/\//.test(url)) {
  throw new Error('Paste the full URL of the release, including https://');
}

const domain = host(f['Your domain'] || url);
const brand = String(f['Your brand name'] || '').trim();
if (!brand) {
  throw new Error('Enter your brand name - it is what every result is checked against.');
}

return [{ json: {
  release_url: url,
  release_host: host(url),
  domain: domain,
  brand: brand,
  brand_key: brand.toLowerCase().replace(/[^a-z0-9]+/g, ''),
}}];

// The phrase picker, which is the entire template.
//
// A release is searched by its own sentences rather than by its brand name,
// because the outlets worth finding are the ones that ran your copy without
// naming you. But the phrase has to be one nobody else has written, and getting
// that right took two live runs.
//
// single-item input: one release fetched, one body to read.
const raw = $input.first().json;
const md = typeof raw === 'string' ? raw : String(raw.data || raw.body || '');
const req = $('Read The Request').first().json;
const cfg = $('Settings').first().json;

if (md.length < 400) {
  throw new Error('The release fetched as ' + md.length + ' bytes, which is not a page. Check the URL - a domain that does not resolve returns an empty body through the Unlocker rather than an error.');
}

// STEP 1: keep only the lines that are prose.
//
// This is the step the first live run did not have, and without it nothing else
// matters. The PR Newswire copy of a real release measured 58,161 bytes on
// 2026-08-27, of which the first ten thousand were navigation - every section of
// the site, as markdown list items full of links. Flattening that into one
// string and splitting on full stops produced "PROLOGIS ANNOUNCES COMMON STOCK
// OFFERING Prologis, Inc." as a top-scoring phrase: three nav headlines glued
// together, which exists on no other page in the world and therefore found
// nothing. Twenty-two lines survive this filter and twenty-one of them are the
// release itself.
const prose = [];
md.split('\n').forEach(function (line) {
  const s = line.trim();
  if (s.length < 80) return;
  if (/^[*\-|>+#]/.test(s)) return;
  // Link density. A nav row is mostly [text](href); a paragraph is mostly words.
  let linkChars = 0;
  s.replace(/\[[^\]]*\]\([^)]*\)/g, function (m) { linkChars += m.length; return m; });
  if (linkChars / s.length > 0.3) return;
  prose.push(
    s.replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
     .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
     .replace(/[*_`~]+/g, ' ')
     .replace(/\s+/g, ' ')
     .trim()
  );
});

if (!prose.length) {
  throw new Error('No prose was found on this page - it is navigation and links only. That usually means the URL is a listing page rather than a single release.');
}

// STEP 2: split into sentences without breaking on abbreviations.
//
// "SAN FRANCISCO, Aug. 4, 2026 /PRNewswire/ -- Prologis, Inc." is one dateline,
// and a naive split on full stops turns it into three fragments, one of which
// scores brilliantly on digits and proper nouns while being pure wire
// boilerplate. Every full stop that is not a sentence end is hidden behind a
// placeholder first and restored afterwards.
const MARK = '\u0001';
const ABBR = /\b(Mr|Mrs|Ms|Dr|Prof|Sr|Jr|St|Inc|Ltd|LLC|LLP|Co|Corp|Pte|Pty|No|vs|etc|al|approx|est|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sept|Sep|Oct|Nov|Dec|Ph|Rev)\./g;

function protect(t) {
  return t
    .replace(ABBR, '$1' + MARK)
    .replace(/\b([A-Z])\./g, '$1' + MARK)
    .replace(/(\d)\.(\d)/g, '$1' + MARK + '$2');
}
function restore(t) {
  return t.split(MARK).join('.');
}

// Position is kept, because a page states its own news before it starts
// advertising other releases. The Prologis page carried two *other* Prologis
// announcements below the body, both perfectly quotable and both about a
// different event - they took the top two slots on an offline run until this
// existed. A weight rather than a cut, so a long release does not lose its
// closing paragraphs.
const sentences = [];
prose.forEach(function (line, li) {
  const where = li / Math.max(1, prose.length);
  const early = where < 0.34 ? 3 : (where < 0.67 ? 1 : 0);
  protect(line).split(/(?<=[.!?])\s+/).forEach(function (frag) {
    const t = restore(frag).trim();
    if (t.length > 40) sentences.push({ text: t, early: early });
  });
});

// Phrases that appear in every release ever written, plus the wire furniture
// that survives the prose filter because it sits inside a real paragraph.
const BOILER = [
  'excited to announce', 'pleased to announce', 'proud to announce',
  'leading provider', 'is a leading', 'look forward to', 'looking forward to',
  'committed to', 'world class', 'best in class', 'industry leading',
  'game changing', 'cutting edge', 'next generation', 'general availability',
  'for more information', 'media contact', 'press contact', 'investor relations',
  'forward looking', 'forward-looking', 'safe harbor', 'safe harbour',
  'all rights reserved', 'terms of service', 'privacy policy', 'cookie policy',
  'subscribe to our', 'sign up for', 'view original content', 'prnewswire',
  'business wire', 'businesswire', 'globe newswire', 'globenewswire', 'cision',
  'list of search results', 'about us',
  // Securities-law furniture. It scores brilliantly - capitalised statute names
  // and four-digit years - and appears verbatim in thousands of filings, so an
  // offline run of the picker against a real acquisition release put
  // "a prospectus meeting the requirements of Section 10 of the Securities Act
  // of 1933" at the top of the list.
  'securities act', 'exchange act', 'registration statement', 'prospectus',
  'shall not constitute an offer', 'in any jurisdiction in which',
  'solicitation of an offer', 'no offer or invitation',
];

// STEP 3: score sliding windows, not whole sentences.
//
// The best fingerprint in a release is usually a clause inside a long sentence,
// and a whole forty-word sentence is a bad search term anyway - one edit by a
// sub-editor and the exact match is gone. Windows of eight to fourteen words are
// long enough to be unique and short enough to survive trimming.
const MIN_W = 8;
const MAX_W = 14;
const scored = [];

sentences.forEach(function (row) {
  const sent = row.text;
  const quoted = /["\u201c]/.test(sent) ? 4 : 0;
  const clean = sent.replace(/["\u201c\u201d\u2018\u2019]/g, '');
  const words = clean.split(/\s+/).filter(Boolean);
  if (words.length < MIN_W) return;

  let best = null;
  for (let start = 0; start + MIN_W <= words.length; start++) {
    for (let len = MIN_W; len <= MAX_W && start + len <= words.length; len++) {
      const win = words.slice(start, start + len);
      const text = win.join(' ');

      // A window has to start on a real word and read as language.
      if (!/^[A-Za-z]/.test(text)) continue;
      if (/[<>{}\[\]()]/.test(text)) continue;
      if (text.indexOf('http') >= 0) continue;

      const lower = text.toLowerCase();

      // The dateline is not a fingerprint at any score. "FRANCISCO, Aug. 4,
      // 2026 /PRNewswire/ -- Prologis, Inc." carries a city, a date, a wire and
      // a company name, which is four kinds of bonus, and it identifies a
      // distribution channel rather than a story. A penalty was not enough to
      // keep it out of the top eight, so the wire markers are a hard reject.
      if (lower.indexOf('prnewswire') >= 0 || lower.indexOf('business wire') >= 0 ||
          lower.indexOf('businesswire') >= 0 || lower.indexOf('globe newswire') >= 0 ||
          lower.indexOf('globenewswire') >= 0 || lower.indexOf('accesswire') >= 0) continue;

      let penalty = 0;
      for (let b = 0; b < BOILER.length; b++) {
        if (lower.indexOf(BOILER[b]) >= 0) penalty += 6;
      }

      // Three or more fully capitalised words is a run of nav headlines that
      // survived the line filter, not a sentence somebody wrote.
      let shouty = 0;
      let proper = 0;
      for (let w = 0; w < win.length; w++) {
        if (/^[A-Z]{3,}$/.test(win[w])) shouty++;
        else if (w > 0 && /^[A-Z][a-z]{2,}/.test(win[w])) proper++;
      }
      if (shouty >= 3) continue;

      const digits = (text.match(/\d/g) || []).length;
      const score = proper * 2 + Math.min(digits, 6) + quoted + row.early - penalty - shouty * 2;
      if (score <= 0) continue;
      if (!best || score > best.score) {
        best = { phrase: text, score: score, proper: proper, digits: digits, quoted: !!quoted };
      }
    }
  }
  if (best) scored.push(best);
});

// One window per sentence already, so this only removes the repeats every
// release has between its headline, its summary and its social card.
const seen = {};
const unique = [];
scored.sort(function (a, b) { return b.score - a.score; });
for (let i = 0; i < scored.length; i++) {
  const key = scored[i].phrase.toLowerCase().slice(0, 40);
  if (seen[key]) continue;
  seen[key] = true;
  unique.push(scored[i]);
}

const cap = Math.max(2, Math.min(10, Number(cfg.max_phrases) || 6));
const picked = unique.slice(0, cap);

if (!picked.length) {
  throw new Error('No distinctive phrase could be found on this page. It is usually a listing page rather than a single release, or the fetch returned navigation only.');
}

// The cleaned body travels with the first phrase. `Measure The Coverage` needs
// it as the denominator for the overlap: measured against the whole 58 KB page,
// a real piece of coverage scored 9.5% because the navigation it will never
// contain was in the divisor. Against the body alone the number means what the
// report says it means.
const proseBody = prose.join(' ');

return picked.map(function (p, idx) {
  return { json: {
    phrase: p.phrase,
    rank: idx + 1,
    score: p.score,
    quoted: p.quoted,
    prose_body: idx === 0 ? proseBody : '',
    // Quoted so Google matches the sentence rather than the words in it, and
    // -site: so the release itself does not take one of the ten slots.
    query: '"' + p.phrase.replace(/"/g, '') + '" -site:' + req.domain,
  }};
});

// One list of pages, plus a verdict on each phrase that produced them.
const phrases = $('Pick The Fingerprints').all().map(function (i) { return i.json; });
const cfg = $('Settings').first().json;
const req = $('Read The Request').first().json;

// Anything that hosts other people's writing will match a phrase without being
// the publisher of it.
const PLATFORMS = [
  'google.com', 'youtube.com', 'facebook.com', 'twitter.com', 'x.com',
  'linkedin.com', 'instagram.com', 'pinterest.', 'reddit.com', 'quora.com',
  't.co', 'bit.ly', 'archive.org', 'webcache', 'translate.goog',
];

function host(u) {
  return String(u || '')
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/[\/?#].*$/, '');
}

// The SERP zone is called with `format: json`, and that returns the whole HTTP
// envelope - { status_code, headers, body } - with the parsed SERP nested in
// `body` as a STRING. Reading `organic` off the top level finds nothing and
// reports a clean sweep, which is the wrong direction to fail in. Measured live
// on 2026-08-27: the node received a 23 KB envelope, `payload.organic` was
// undefined, and a query that returned ten real results in curl reported zero.
function unwrapSerp(x) {
  let p = x;
  if (p && p.body != null) p = p.body;
  if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { p = {}; }
  } else if (p && typeof p.data === 'string') {
    try { p = JSON.parse(p.data); } catch (e) { p = {}; }
  } else if (p && p.data && typeof p.data === 'object') {
    p = p.data;
  }
  return p || {};
}

const pages = {};
const phraseReport = [];

$input.all().forEach(function (item, idx) {
  const p = phrases[idx] || { phrase: '(unknown)', rank: idx + 1 };
  const body = unwrapSerp(item.json);

  // Bright Data answers validation errors and rate limits with HTTP 200 and an
  // error body, and neverError means nothing throws. A phrase that errored is
  // not a phrase that found nothing, and the report has to be able to say which.
  if (body && body.error) {
    phraseReport.push({ phrase: p.phrase, rank: p.rank, hits: 0, on_brand: 0, verdict: 'search failed' });
    return;
  }

  const organic = (body && body.organic) || [];
  const mine = [];
  let onBrand = 0;

  organic.forEach(function (r) {
    const h = host(r.link);
    // Google occasionally returns its own redirect wrapper instead of the
    // publisher - measured 2026-08-27 as https://www.google.com/goto?url=CAESc...
    // It is not a page and cannot be fetched, so it goes by host.
    if (!h || h.indexOf('google.') === 0) return;
    if (h === req.domain || h.slice(-(req.domain.length + 1)) === '.' + req.domain) return;
    // The wire is where you published, not somewhere that picked you up. Excluded
    // separately from the brand domain, because a release very often lives on a
    // host the company does not own - prnewswire.com, businesswire.com, an
    // investor-relations subdomain - and -site: on the brand domain alone leaves
    // it in every result.
    if (h === req.release_host || h.slice(-(req.release_host.length + 1)) === '.' + req.release_host) return;
    let skip = false;
    for (let i = 0; i < PLATFORMS.length; i++) {
      if (h.indexOf(PLATFORMS[i]) >= 0) { skip = true; break; }
    }
    if (skip) return;

    const blob = ((r.title || '') + ' ' + (r.description || '')).toLowerCase().replace(/[^a-z0-9]+/g, '');
    const named = blob.indexOf(req.brand_key) >= 0;
    if (named) onBrand++;
    mine.push({ host: h, link: String(r.link), title: String(r.title || ''), named: named });
  });

  // The check that stops the report filling up with strangers. A phrase that
  // returned results, of which almost none mention the brand, was boilerplate
  // however well it scored beforehand - which is exactly what happened to
  // "we are excited to announce the general availability" in testing: ten hits,
  // ten other companies, zero on brand.
  const ratio = mine.length ? onBrand / mine.length : 0;
  const boilerplate = mine.length >= 4 && ratio < 0.34;

  phraseReport.push({
    phrase: p.phrase, rank: p.rank, hits: mine.length, on_brand: onBrand,
    verdict: boilerplate ? 'boilerplate, discarded' : (mine.length ? 'used' : 'no pickup'),
  });

  if (boilerplate) return;

  mine.forEach(function (m) {
    if (pages[m.link]) {
      pages[m.link].phrases.push(p.rank);
      return;
    }
    pages[m.link] = {
      url: m.link, host: m.host, serp_title: m.title,
      named_in_serp: m.named, phrases: [p.rank],
    };
  });
});

const cap = Math.max(1, Math.min(25, Number(cfg.max_pages) || 10));
const list = Object.keys(pages).map(function (k) { return pages[k]; });

// Sorted so the budget goes to pages matched by more than one phrase - those ran
// a real chunk of the release rather than sharing one sentence by accident.
list.sort(function (a, b) { return b.phrases.length - a.phrases.length; });

const chosen = list.slice(0, cap);
if (!chosen.length) {
  // Not an error. A release nobody picked up is a finding, and it has to reach
  // the report rather than end the branch here.
  return [{ json: {
    url: '', host: '', no_pickup: true,
    phrase_report: phraseReport, dropped: 0,
  }}];
}

return chosen.map(function (c) {
  return { json: Object.assign({}, c, {
    phrase_report: phraseReport,
    dropped: Math.max(0, list.length - cap),
  })};
});

// How much of the release survived, and whether they linked. Both are
// arithmetic; neither needs a model.
const req = $('Read The Request').first().json;
const cands = $('Collect The Hits').all();
const items = $input.all();

// The release BODY, not the release page. `Pick The Fingerprints` already threw
// away the navigation, so the cleaned prose is read back from it rather than
// re-derived - and the denominator below is then the text somebody wrote instead
// of the text plus every menu on the wire's website.
const releaseText = String($('Pick The Fingerprints').first().json.prose_body || '').toLowerCase();
if (!releaseText) {
  throw new Error('The cleaned release body did not reach this node. Check that Pick The Fingerprints still emits prose_body on its first item.');
}

// Overlapping five-word windows. Long enough that ordinary English does not
// collide by chance, short enough to survive a sub-editor trimming a sentence.
function shingles(text) {
  const w = text.replace(/[^a-z0-9 ]+/g, ' ').split(/\s+/).filter(Boolean);
  const out = {};
  for (let i = 0; i + 5 <= w.length; i++) {
    out[w.slice(i, i + 5).join(' ')] = true;
  }
  return out;
}

const releaseShingles = shingles(releaseText);
const releaseKeys = Object.keys(releaseShingles);

const out = [];
for (let i = 0; i < items.length; i++) {
  const cand = cands[i].json;
  if (cand.no_pickup) {
    out.push({ json: Object.assign({}, cand) });
    continue;
  }

  const raw = items[i].json;
  const md = typeof raw === 'string' ? raw : String(raw.data || raw.body || '');
  const flat = md.replace(/\s+/g, ' ');
  const lower = flat.toLowerCase();

  // A page that did not fetch is not a page that did not link. Say which.
  if (md.length < 500) {
    out.push({ json: Object.assign({}, cand, {
      fetched: false, copy_pct: 0, links_to_you: false,
      brand_in_headline: false, byline: '', page_text: '',
    })});
    continue;
  }

  let shared = 0;
  const pageShingles = shingles(lower);
  for (let k = 0; k < releaseKeys.length; k++) {
    if (pageShingles[releaseKeys[k]]) shared++;
  }
  const copyPct = releaseKeys.length ? Math.round((shared / releaseKeys.length) * 1000) / 10 : 0;

  // A link to the domain, in any form the markdown could carry it, but not the
  // page's own host - a wire syndicator quoting its own URL is not a link to you.
  const linkRe = new RegExp('https?://(www\\.)?' + req.domain.replace(/\./g, '\\.'), 'i');
  const linksToYou = linkRe.test(flat);

  // The first heading the markdown carries, which is the headline on almost every
  // article template - but a heading is frequently a logo, and
  // `# [![Financier Worldwide](//images.squarespace-cdn.com/...)](/)` is a
  // heading by every structural measure. Strip the image and link syntax first,
  // then fall back to the SERP title if what is left is not words.
  let headline = '';
  const headingMatch = md.match(/^#{1,3}\s+(.+)$/m);
  if (headingMatch) {
    headline = headingMatch[1]
      .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
      .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
      .replace(/\s+/g, ' ')
      .trim();
  }
  const letters = (headline.match(/[A-Za-z]/g) || []).length;
  if (letters < 12 || letters / Math.max(1, headline.length) < 0.5) {
    headline = String(cand.serp_title || '');
  }
  const brandInHeadline = headline.toLowerCase().replace(/[^a-z0-9]+/g, '').indexOf(req.brand_key) >= 0;

  // A byline if the page volunteers one. It is used to address the draft to a
  // person by name - never to look up an address.
  const byMatch = flat.match(/\bBy\s+([A-Z][a-z]+(?:\s+[A-Z][a-z'\-]+){1,2})/);
  const byline = byMatch ? byMatch[1] : '';

  out.push({ json: Object.assign({}, cand, {
    fetched: true,
    headline: headline.slice(0, 200),
    copy_pct: copyPct,
    links_to_you: linksToYou,
    brand_in_headline: brandInHeadline,
    names_brand: lower.replace(/[^a-z0-9]+/g, '').indexOf(req.brand_key) >= 0,
    byline: byline,
    page_text: flat.slice(0, 3500),
  })});
}
return out;

parameters.text:
=Brand: {{ $json.brand_key }}
Outlet: {{ $json.host }}
Headline: {{ $json.headline }}
Shares {{ $json.copy_pct }}% of the release wording. Links to the brand: {{ $json.links_to_you }}. Names the brand in the headline: {{ $json.brand_in_headline }}.

Article:
{{ $json.page_text }}

angle: one sentence on the frame this outlet put on the announcement. Say what they led with, not what the announcement said.
what_they_cut: the substantive part of the announcement that is missing here, or the single word none.
tone must be exactly one of: positive, neutral, sceptical, negative.
follow_up: only if the article does NOT link to the brand. Two or three sentences to the outlet, from the company, which (a) thanks them for the coverage naming something specific they actually wrote, and (b) asks for a link to the source. No flattery, no marketing language, no subject line, no greeting and no sign-off. If the article already links to the brand, return an empty string.

Everything you write must be supported by the article text above. Do not describe coverage that is not there.

parameters.jsonSchemaExample:
{
  "angle": "one sentence on the frame they put on it",
  "what_they_cut": "the part of the announcement they left out, or none",
  "tone": "neutral",
  "follow_up": "two or three sentences to the outlet, or an empty string"
}

