// Merge the arithmetic with the reading, and normalise the model's enum.
const measured = $('Measure The Coverage').all().map(function (i) { return i.json; });
const req = $('Read The Request').first().json;

const TONES = { positive: 1, neutral: 1, sceptical: 1, negative: 1 };

// Hosts that will carry your release in full and are not publications: statutory
// filing archives and stock-quote databases. They belong in the report - a
// filing is a real pickup and worth seeing - but never in an outreach draft.
// Measured 2026-08-27, when an earlier version of this node cheerfully prepared
// a note to sec.gov thanking it for its coverage and asking for a backlink.
const NO_OUTREACH = [
  'sec.gov', '.gov', 'gov.uk', 'europa.eu', 'edgar', 'secdatabase',
  'stockanalysis.com', 'stocktitan', 'marketbeat', 'quiverquant', 'webull',
  'moomoo', 'wallmine', 'simplywall.st', 'barchart', 'investing.com',
  'tradingview', 'marketscreener', 'tiblio', 'annualreports',
];

return measured.map(function (m, idx) {
  if (m.no_pickup) return { json: m };

  const item = $input.all()[idx];
  // The Information Extractor nests its result under `output`. Reading
  // $json.angle instead of $json.output.angle returns undefined on every item,
  // which produces an empty report on a run where every node is green.
  const j = (item && item.json && item.json.output) || (item && item.json) || {};

  let tone = String(j.tone || '').toLowerCase().trim();
  if (!TONES[tone]) tone = 'neutral';

  const floor = Number($('Settings').first().json.min_copy_pct) || 8;
  const followUp = String(j.follow_up || '').trim();

  // Three gates, and the arithmetic overrules the model on all three. Measured
  // 2026-08-27: a stock-quote aggregator sharing 5% of the wording was handed a
  // fluent draft thanking it for its coverage, which would have been an
  // embarrassing thing to send. A page has to have actually used your words, to
  // actually name you, and to actually be missing the link.
  const reused = m.copy_pct >= floor && m.names_brand;

  let publication = true;
  const h = String(m.host || '').toLowerCase();
  for (let i = 0; i < NO_OUTREACH.length; i++) {
    if (h.indexOf(NO_OUTREACH[i]) >= 0) { publication = false; break; }
  }

  const needsFollowUp = !!followUp && !m.links_to_you && m.fetched && reused && publication;

  // A page that never fetched has no angle. The model still gets asked - it is
  // one cheap call and skipping it would need a branch that could go empty - but
  // what it invents about an empty page is not reported.
  return { json: Object.assign({}, m, {
    angle: m.fetched ? String(j.angle || '').trim() : '',
    what_they_cut: m.fetched ? String(j.what_they_cut || '').trim() : '',
    reused_your_words: reused,
    is_publication: publication,
    tone: tone,
    needs_follow_up: needsFollowUp,
    draft_subject: needsFollowUp
      ? 'Thanks for the ' + req.brand + ' coverage - one small ask'
      : '',
    draft_body: needsFollowUp
      ? followUp +
        '\n\n---\nArticle: ' + m.url +
        '\nWriter: ' + (m.byline || 'not named on the page') +
        '\nShares ' + m.copy_pct + '% of the release wording.' +
        '\n\nThis draft has no recipient. Read the article, then address it yourself.'
      : '',
  })};
});

// One report, rendered as HTML because the form completion node writes its text
// into the page raw - a report joined with newlines collapses into one paragraph.
const rows = $input.all().map(function (i) { return i.json; });
const req = $('Read The Request').first().json;
const phraseReport = (rows[0] && rows[0].phrase_report) || [];
const dropped = (rows[0] && rows[0].dropped) || 0;

const F = 'system-ui,-apple-system,sans-serif';
function esc(s) {
  return String(s === null || s === undefined ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

const found = rows.filter(function (r) { return !r.no_pickup && r.fetched; });
const unfetched = rows.filter(function (r) { return !r.no_pickup && !r.fetched; });
const linked = found.filter(function (r) { return r.links_to_you; });
const unlinked = found.filter(function (r) { return !r.links_to_you; });
const drafted = found.filter(function (r) { return r.needs_follow_up; });
const boiler = phraseReport.filter(function (p) { return p.verdict === 'boilerplate, discarded'; });

const blocks = [];
blocks.push('<h2 style="font-size:20px;margin:0 0 4px">Who picked up ' + esc(req.brand) + '</h2>');

if (!found.length) {
  blocks.push('<p style="font:15px/1.6 ' + F + ';color:#111">No outlet outside ' +
    esc(req.domain) + ' was found running these sentences. That is a real result rather than an error - it usually means the release has not been syndicated, or it went out too recently to be indexed.</p>');
} else {
  blocks.push('<div style="color:#111;font:15px/1.6 ' + F + ';margin:0 0 20px">' +
    found.length + ' page(s) carried your wording &nbsp;|&nbsp; <b>' + linked.length +
    ' linked</b> &nbsp;|&nbsp; ' + unlinked.length + ' did not</div>');

  found.sort(function (a, b) { return b.copy_pct - a.copy_pct; });
  found.forEach(function (r) {
    const colour = r.links_to_you ? '#0a7d33' : '#a11';
    blocks.push(
      '<div style="border-left:3px solid ' + colour + ';padding:2px 0 2px 12px;margin:0 0 18px;font:14px/1.55 ' + F + '">' +
      '<div><a href="' + esc(r.url) + '" style="color:#0a58ca;text-decoration:none"><b>' + esc(r.host) + '</b></a>' +
      ' &nbsp;<span style="color:#888">' + r.copy_pct + '% of your wording' +
      (r.brand_in_headline ? ', named in the headline' : '') +
      (r.links_to_you ? ', linked' : (r.reused_your_words ? ', <b style="color:#a11">no link</b>' : ', no link, little reuse')) +
      (r.byline ? ', by ' + esc(r.byline) : '') + '</span></div>' +
      (r.headline ? '<div style="color:#111;margin-top:3px">' + esc(r.headline) + '</div>' : '') +
      (r.angle ? '<div style="color:#444;margin-top:4px">' + esc(r.angle) + '</div>' : '') +
      (r.what_they_cut && r.what_they_cut.toLowerCase() !== 'none'
        ? '<div style="color:#9a6700;margin-top:4px">Left out: ' + esc(r.what_they_cut) + '</div>' : '') +
      '</div>'
    );
  });
}

if (phraseReport.length) {
  blocks.push('<h3 style="font-size:15px;margin:22px 0 8px">The sentences that were searched</h3>');
  blocks.push('<ul style="font:13px/1.6 ' + F + ';color:#444;margin:0 0 16px;padding-left:20px">' +
    phraseReport.map(function (p) {
      return '<li>' + esc(p.phrase.slice(0, 110)) + ' <span style="color:#999">(' +
        p.hits + ' hit(s), ' + p.on_brand + ' on brand - ' + esc(p.verdict) + ')</span></li>';
    }).join('') + '</ul>');
}

if (boiler.length) {
  blocks.push('<p style="font:13px/1.6 ' + F + ';color:#9a6700">' + boiler.length +
    ' sentence(s) were discarded after searching: they returned results, but almost none mentioned ' +
    esc(req.brand) + '. That is the signature of boilerplate, and keeping them would have filled this report with strangers.</p>');
}

const notes = [];
if (dropped) notes.push(dropped + ' further page(s) matched but were not fetched - raise max_pages.');
if (unfetched.length) notes.push(unfetched.length + ' page(s) could not be fetched and were not judged.');
if (drafted.length) notes.push(drafted.length + ' Gmail draft(s) were prepared. None was sent, and none has a recipient.');
if (unlinked.length > drafted.length) notes.push((unlinked.length - drafted.length) + ' unlinked page(s) got no draft - they share too little of your wording to be coverage.');
if (notes.length) {
  blocks.push('<p style="font:12px/1.6 ' + F + ';color:#999">' + esc(notes.join(' ')) + '</p>');
}

const html = '<div style="max-width:760px;margin:0 auto;text-align:left;font:15px/1.6 ' + F + '">' +
  blocks.join('') + '</div>';

const slack = [];
slack.push('*Coverage check* - ' + req.brand + ': ' + found.length +
  ' page(s) ran your wording, ' + linked.length + ' linked, ' + unlinked.length + ' did not.');
found.slice(0, 8).forEach(function (r) {
  slack.push((r.links_to_you ? ':white_check_mark:' : ':link:') + ' <' + r.url + '|' + r.host +
    '> - ' + r.copy_pct + '% copied' + (r.angle ? ' - ' + r.angle.slice(0, 120) : ''));
});
if (drafted.length) slack.push('_' + drafted.length + ' follow-up draft(s) are waiting in Gmail. Nothing was sent._');

return [{ json: { html: html, message: slack.join('\n') } }];
